{
  "rules": [
    {
      "category": "rent_increase_limit",
      "title": "Annual rent increase limit (CPI cap up to 4%)",
      "requirement": "Landlords may not increase rent more than once in a 12-month period, capped at the percentage increase in the CPI (CPI-U for NY-Northern NJ-Long Island) over the specified 12-month comparison window, up to a maximum of 4%. The dwelling must also be registered and in substantial compliance with applicable housing and safety codes.",
      "requirement_es": "Los propietarios no pueden aumentar el alquiler más de una vez en un período de 12 meses, con un límite según el aumento porcentual del IPC (CPI-U para NY-Northern NJ-Long Island) hasta un máximo del 4%. La vivienda también debe estar registrada y cumplir sustancialmente con los códigos de vivienda y seguridad aplicables.",
      "key_value": {
        "label": "annual cap",
        "value": "CPI, max 4%"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Owner-occupied buildings of 1 to 4 units",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true,
                "note": "owner-occupied one (1), two (2), three (3) or four (4) family housing space units"
              },
              {
                "field": "units",
                "operator": "<=",
                "value": 4,
                "note": "owner-occupied one (1), two (2), three (3) or four (4) family housing space units"
              }
            ]
          }
        },
        {
          "description": "Public housing",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "government",
                "note": "all public housing"
              }
            ]
          }
        },
        {
          "description": "Units rehabilitated under Federal/State Rental Rehabilitation Programs receiving Section 8 or vouchers (during program tenure)",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true,
                "note": "rehabilitated by Federal/State Rental Rehabilitation Programs and receiving Section 8 or Federal housing vouchers"
              }
            ]
          }
        },
        {
          "description": "Newly constructed multiple dwellings for the period of amortization of initial mortgage or 30 years following completion of construction, whichever is less",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "building_age_years",
                "operator": "<=",
                "value": 30,
                "note": "newly constructed multiple dwellings for a period not to exceed initial mortgage amortization or 30 years"
              },
              {
                "field": "units",
                "operator": ">=",
                "value": 3,
                "note": "multiple dwellings containing three (3) or more apartments"
              }
            ]
          }
        },
        {
          "description": "Motel or hotel space rented on a day-to-day basis to transients, or commercial use rentals",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "other",
                "note": "any motel or hotel space rented on a day-to-day basis to transients; commercial use"
              }
            ]
          }
        }
      ],
      "effective_date": "2017-09-05",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Fine of not more than $500, imprisonment for not more than 90 days, or both; or municipal court monetary penalty not exceeding $500 per housing space violation. Landlord must rebate excess rent collected.",
      "source_citation": "Newark Rev. Gen. Ord. tit. XIX, ch. 2, §§ 19:2-3.1, 19:2-3.2, 19:2-4, 19:2-19",
      "quote": {
        "chunk": "c10",
        "start_words": "At the expiration of a lease or at the termination",
        "end_words": "rent increase exceed four (4%) percent."
      },
      "confidence": 0.95
    }
  ]
}
